-- =============================================================================
-- File   : db/schema/003_vector.sql
-- Purpose: pgvector - semantic search over events
--   * Embedding model : Xenova/all-MiniLM-L6-v2  -> 384 dimensions
--   * Distance metric : cosine distance (operator <=>), similarity = 1 - distance
--   * Index           : HNSW with vector_cosine_ops
-- Embeddings are generated by the application (src/lib/embeddings) and stored
-- with: UPDATE events SET embedding = $1::vector WHERE event_id = $2
-- =============================================================================
CREATE EXTENSION IF NOT EXISTS vector;

ALTER TABLE events ADD COLUMN embedding vector(384);

CREATE INDEX idx_events_embedding_hnsw ON events USING hnsw (embedding vector_cosine_ops);

-- Semantic search: events closest to a query embedding
CREATE OR REPLACE FUNCTION semantic_search_events(p_query vector(384), p_limit INTEGER DEFAULT 10)
RETURNS TABLE (event_id INTEGER, title VARCHAR, similarity DOUBLE PRECISION)
LANGUAGE sql STABLE AS $$
    SELECT e.event_id, e.title, 1 - (e.embedding <=> p_query) AS similarity
    FROM events e
    WHERE e.embedding IS NOT NULL AND e.status = 'published'
    ORDER BY e.embedding <=> p_query
    LIMIT p_limit
$$;

-- "More like this": nearest neighbours of an existing event's embedding
CREATE OR REPLACE FUNCTION similar_events(p_event_id INTEGER, p_limit INTEGER DEFAULT 4)
RETURNS TABLE (event_id INTEGER, title VARCHAR, similarity DOUBLE PRECISION)
LANGUAGE sql STABLE AS $$
    SELECT o.event_id, o.title, 1 - (o.embedding <=> s.embedding) AS similarity
    FROM events s
    JOIN events o ON o.event_id <> s.event_id
    WHERE s.event_id = p_event_id AND s.embedding IS NOT NULL
      AND o.embedding IS NOT NULL AND o.status = 'published'
    ORDER BY o.embedding <=> s.embedding
    LIMIT p_limit
$$;
